mapper.select:
SELECT q.id, q.quote_no, q.quote_name, q.opportunity_id, o.opp_name AS opportunity_name, q.customer_id, c.customer_name, q.total_amount, q.discount_rate, q.final_amount, q.status, q.expire_date, q.send_time, q.accept_time, q.remark, q.owner_id, u.user_name AS owner_name, q.create_time, q.update_time FROM crm_quote q LEFT JOIN crm_customer c ON q.customer_id = c.id LEFT JOIN crm_opportunity o ON q.opportunity_id = o.id LEFT JOIN sys_user u ON q.owner_id = u.id WHERE 1=1
AND q.quote_name LIKE CONCAT('%', #{query.quoteName}, '%')
AND q.quote_no LIKE CONCAT('%', #{query.quoteNo}, '%')
AND q.opportunity_id = #{query.opportunityId}
AND q.customer_id = #{query.customerId}
AND q.status = #{query.status}
AND q.owner_id = #{query.ownerId}
ORDER BY q.create_time DESC
